// Day boundaries and formatting in the viewer's own timezone (the browser's
// resolved timezone). The server sends raw UTC timestamps; the page turns them
// into words locally so cached HTML can be shared between timezones.

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

// Main entry point for <time> rendering. `format` matches the server helper's
// `format:` argument (dasherized). `now` is injectable for testing.
export function formatLocalTime(date, format = "relative", now = new Date()) {
  const normalized = normalizeFormat(format)

  switch (normalized) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDate(date)
    case "date-with-year":
    case "date-withyear":
    case "long-date":
      return formatDateWithYear(date)
    case "weekday-date":
    case "weekday":
    case "day":
      return formatWeekdayDate(date)
    case "short-datetime":
    case "short-date-time":
    case "datetime":
      return formatShortDatetime(date)
    case "relative":
    case "friendly":
    case "calendar":
    case "smart":
    case "ago":
    case "duration":
      return formatFriendly(date, now)
    default:
      return formatFriendly(date, now)
  }
}

export function formatTime(date) {
  return normalizeSpaces(new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }).format(date))
}

export function formatDate(date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric"
  }).format(date)
}

export function formatDateWithYear(date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric"
  }).format(date)
}

export function formatWeekdayDate(date) {
  return new Intl.DateTimeFormat("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric"
  }).format(date)
}

export function formatShortDatetime(date) {
  return normalizeSpaces(new Intl.DateTimeFormat("en-US", {
    month: "numeric",
    day: "numeric",
    year: "2-digit",
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }).format(date))
}

// Smart calendar-relative formatting in the viewer's timezone:
//
//   same day        -> "1:42 PM"
//   yesterday       -> "yesterday"
